export function decodeAllergies(score) {
    const names = ['eggs', 'peanuts', 'shellfish', 'strawberries', 'tomatoes', 'chocolate', 'pollen', 'cats'];
    return names.filter((_, i) => (score & (1 << i)) !== 0);
}
